# owner: platform
"""Snapping span times to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.models import Span


def _snap(value: int, step: int) -> int:
    """Nearest multiple of step, with halves rounding up."""
    return (value + step // 2) // step * step


def _clock(value: int) -> str:
    return f"{value // 60:02d}:{value % 60:02d}"


def _label(span: Span) -> str:
    hours, mins = divmod(span.minutes, 60)
    return (
        f"{_clock(span.start)}-{_clock(span.end)} "
        f"({hours}h {mins:02d}m)"
    )


def round_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Labels like 09:00-17:15 (8h 15m), times snapped to step."""
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step}")
    return [
        _label(Span(_snap(item.start, step), _snap(item.end, step)))
        for item in spans
    ]
