        spans = [Span(8 * 60 + 7, 9 * 60 + 53)]
        self.assertEqual(
            round_spans(spans, 15), ["08:00-10:00 (2h 00m)"]
        )

    def test_empty(self):
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, posix := 45):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)
