    return (value + step // 2) // step * step


def _clock(value: int) -> str:
    return f"{value // 60:02d}:{value % 60:02d}"


def _label(span: Span) -> str:
    hours, mins = divmod(span.minutes, 60)
    start, end = _clock(span.start), _clock(span.end)
    return f"{start}-{end} ({hours}h {mins:02d}m)"


def _round(item: Span, step: int) -> str:
    start = _snap(item.start, step)
    return _label(Span(start, _snap(item.end, step)))


